import{_ as p,a0 as l,w as i,s,I as o,x as e,a1 as a,A as r,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"一个可以显示Linux命令运行进度的伟大工具 | LCTT x X-CMD","titleTemplate":false,"description":"一个可以显示Linux命令运行进度的伟大工具 | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一个可以显示Linux命令运行进度的伟大工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一个可以显示Linux命令运行进度的伟大工具 | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/20141222 A Great Tool To Show Linux Command Progress Like ETA","title":"一个可以显示Linux命令运行进度的伟大工具","tag":"201501","desc":""},"relativePath":"201501/20141222 A Great Tool To Show Linux Command Progress Like ETA.md","filePath":"[post].md"}'),c={name:"201501/20141222 A Great Tool To Show Linux Command Progress Like ETA.md"};function m(u,t,g,x,h,v){const n=l("Link");return i(),s("div",null,[t[16]||(t[16]=o("h1",{id:"一个可以显示linux命令运行进度的伟大工具",tabindex:"-1"},[e("一个可以显示Linux命令运行进度的伟大工具 "),o("a",{class:"header-anchor",href:"#一个可以显示linux命令运行进度的伟大工具","aria-label":"Permalink to “一个可以显示Linux命令运行进度的伟大工具”"},"​")],-1)),t[17]||(t[17]=o("p",null,[e("Coreutils Viewer（"),o("strong",null,"cv"),e("）是一个简单的程序，它可以用于显示任何核心组件命令（如：cp、mv、dd、tar、gzip、gunzip、cat、grep、fgrep、egrep、cut、sort、xz、exiting）的进度。它使用文件描述信息来确定一个命令的进度，比如cp命令。"),o("strong",null,"cv"),e("之美在于，它能够和其它Linux命令一起使用，比如你所知道的watch以及I/O重定向命令。这样，你就可以在脚本中使用，或者你能想到的所有方式，别让你的想象力束缚住你。")],-1)),t[18]||(t[18]=o("h3",{id:"安装",tabindex:"-1"},[e("安装 "),o("a",{class:"header-anchor",href:"#安装","aria-label":"Permalink to “安装”"},"​")],-1)),o("p",null,[t[1]||(t[1]=e("你可以从cv的",-1)),a(n,{href:"http://github.com/Xfennec/cv"},{default:r(()=>[...t[0]||(t[0]=[e("github仓库那儿",-1)])]),_:1}),t[2]||(t[2]=e("下载所需的源文件。把zip文件下载下来后，将它解压缩，然后进入到解压后的文件夹。",-1))]),t[19]||(t[19]=d(`<p>该程序需要<strong>ncurses library</strong>。如果你已经在你的Linux系统中安装了ncurses，那么cv的安装过程对你而言就是那么的轻松写意。</p><p>通过以下两个简单步骤来进行编译和安装吧。</p><pre><code>$ make
$ sudo make install
</code></pre><h3 id="运行cv" tabindex="-1">运行cv <a class="header-anchor" href="#运行cv" aria-label="Permalink to “运行cv”">​</a></h3><p>要运行cv，只需要想其它程序一样，在命令行输入此命令即可。如果你没有执行make install，而选择从当前目录中去运行，那么你可以运行以下命令：</p><pre><code>$ ./cv
</code></pre><p>否则，就运行以下命令吧。</p><pre><code>$ cv
</code></pre><p>如果没有核心组件命令在运行，那么cv程序会退出，并告诉你：没有核心组件命令在运行。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/11/cv-no-command.png" alt="cv no command"></p><p>要有效使用该程序，请在你系统上运行某个核心组件程序。在本例中，我们将使用<strong>cp</strong>命令。</p><p>当拷贝一个打文件时，你就可以看到当前进度了，以百分比显示。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/11/cv-default.png" alt="cv default"></p><h3 id="添加选项到-cv" tabindex="-1">添加选项到 cv <a class="header-anchor" href="#添加选项到-cv" aria-label="Permalink to “添加选项到 cv”">​</a></h3><p>你也可以添加几个选项到cv命令，就像其它命令一样。一个有用的选项是让你了解到拷贝或移动大文件时的预计剩余时间。</p><p>添加<strong>-w</strong>选项，它就会帮你显示预计的剩余时间。</p><pre><code>$ cv -w
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/11/cv-estimated-throughput.png" alt="cv estimated throughput"></p><p>试着添加更多的命令选项吧。像下面这样添加其它选项：</p><pre><code>$ cv -wq
</code></pre><h3 id="cv-和-watch-命令" tabindex="-1">cv 和 watch 命令 <a class="header-anchor" href="#cv-和-watch-命令" aria-label="Permalink to “cv 和 watch 命令”">​</a></h3><p>watch是一个用于周期性运行程序并显示输出结果的程序。有时候，你可能想要持续看看命令运行状况而不想将 cv 的结果存储到日志文件中。在这种情况下，watch就会派上用场了，它可以和cv一起使用。</p><pre><code>$ watch cv -qw
</code></pre><p>该命令将会显示所有运行着的核心组件命令的实例。它也会显示进度和预计完成时间。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/11/cv-and-watch-e1416519384265.png" alt="cv and watch"></p><h3 id="在日志文件中查看输出结果" tabindex="-1">在日志文件中查看输出结果 <a class="header-anchor" href="#在日志文件中查看输出结果" aria-label="Permalink to “在日志文件中查看输出结果”">​</a></h3><p>正如其所承诺的那样，你可以使用cv来重定向它的输出结果到一个日志文件。这功能在命令运行太快而看不到任何有意义的内容时特别有用。</p><p>要在日志文件中查看进度，你仅仅需要重定向输出结果，就像下面这样。</p><pre><code>$ cv -w &gt;&gt; log.txt
</code></pre><p>要查看该命令的输出结果，请用你喜爱的文本编辑器打开日志文件，也可以用cat命令，就像下面这样：</p><pre><code>$ cat log.txt
</code></pre><h3 id="获得帮助" tabindex="-1">获得帮助 <a class="header-anchor" href="#获得帮助" aria-label="Permalink to “获得帮助”">​</a></h3><p>如果你在任何地方受到阻碍，你总是可以通过查阅手册页或使用help选项来获取帮助信息。 要获取帮助信息，可以使用带<strong>-h</strong>选项的cv命令。</p><pre><code>$ cv -h
</code></pre><p>如果需要更多详细信息，那么手册页是个很不错的地方。</p><pre><code>$ man cv
</code></pre><p>但是，要获取上述手册页，你必须执行make install来安装cv。</p><p>耶！现在，你的Linux工具箱中又多了个伟大的工具。 你学会么？亲自去试试吧~</p><hr>`,39)),o("p",null,[t[4]||(t[4]=e("via: ",-1)),a(n,{href:"http://linoxide.com/linux-command/tool-show-command-progress/"},{default:r(()=>[...t[3]||(t[3]=[e("http://linoxide.com/linux-command/tool-show-command-progress/",-1)])]),_:1})]),o("p",null,[t[8]||(t[8]=e("作者：",-1)),a(n,{href:"http://linoxide.com/author/allan/"},{default:r(()=>[...t[5]||(t[5]=[e("Allan Mbugua",-1)])]),_:1}),t[9]||(t[9]=e(" 译者：",-1)),a(n,{href:"https://github.com/GOLinux"},{default:r(()=>[...t[6]||(t[6]=[e("GOLinux",-1)])]),_:1}),t[10]||(t[10]=e(" 校对：",-1)),a(n,{href:"https://github.com/wxy"},{default:r(()=>[...t[7]||(t[7]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[13]||(t[13]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原创翻译，",-1)),a(n,{href:"http://linux.cn/"},{default:r(()=>[...t[12]||(t[12]=[e("Linux中国",-1)])]),_:1}),t[15]||(t[15]=e(" 荣誉推出",-1))])])}const L=p(c,[["render",m]]);export{w as __pageData,L as default};
